const paths={leaf:'M4 20C4 8 9 4 21 3c0 13-5 18-13 15M5 20 16 9M12 15C5 17 2 13 3 7c6 0 9 2 10 6',shield:'M12 2 3 6v6c0 5 5 8 9 10 4-2 9-5 9-10V6Z',heart:'M12 21 3 12C-3 5 6-1 12 6c6-7 15-1 9 6Z',fruit:'M11 6c-5-5-12 2-7 11 3 6 13 6 16-1 4-8-2-13-7-10M12 7V2m0 2c3-3 6-2 6-2',can:'M7 3h10l1 3v15H6V6Zm-1 4h12M8 1h8',pack:'M3 8h18v13H3Zm5 0V4h8v4M3 12h18',store:'M3 10V6l2-3h14l2 3v4M3 10c0 3 5 3 5 0 0 3 8 3 8 0 0 3 5 3 5 0M4 13v8h16v-8M9 21v-6h6v6',cart:'M2 3h3l3 13h11l3-10H6M9 20h.01M18 20h.01',cup:'M3 8h14v7c0 8-14 8-14 0Zm14 1h3c4 0 4 6-3 6M6 5c-3-3 3-2 0-5M11 5c-3-3 3-2 0-5'};
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[el.dataset.icon]}"/></svg>`});
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')});
const modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');function show(html){content.innerHTML=html;modal.showModal()}document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
document.querySelector('#join').onclick=()=>{show('<p class="eyebrow">Clube VITTAIA</p><h2>Seu sabor favorito,<br>sempre por perto.</h2><p>Escolha como seria sua assinatura.</p><label for="frequency">Frequência de entrega</label><select id="frequency"><option>A cada 15 dias</option><option selected>Uma vez por mês</option></select><label for="club-packs">Packs por entrega</label><select id="club-packs"><option value="1">1 pack · R$ 48,00</option><option value="2">2 packs · R$ 96,00</option><option value="3">3 packs · R$ 144,00</option></select><button class="button green" id="club-confirm">Simular minha assinatura</button><small>Proposta acadêmica. Nenhuma assinatura ou cobrança será criada. Frete não incluído.</small>');document.querySelector('#club-confirm').onclick=()=>{const frequency=document.querySelector('#frequency').value;const count=document.querySelector('#club-packs').value;show(`<h2>Uma rotina mais VITTAIA.</h2><p>Sua escolha: <strong>${count} pack(s)</strong>, ${frequency.toLowerCase()}.</p><p>Valor por entrega: <strong>${money(count*48)}</strong> + frete.</p><small>Simulação concluída. Nenhuma assinatura foi criada.</small>`)}};
document.querySelector('#locations').onclick=()=>show('<p class="eyebrow">Onde encontrar</p><h2>Novos caminhos para um novo sabor.</h2><p>A VITTAIA é uma marca fictícia criada para o TCC e ainda não possui pontos de venda reais.</p><p>Empórios naturais, lojas de orgânicos, mercados e cafés representam os canais propostos para a marca.</p><a class="button" href="#comprar" id="go-buy">Conhecer o pack</a>');content.addEventListener('click',e=>{if(e.target.id==='go-buy')modal.close()});
const reviews=[['Leve e diferente','Um sabor bem diferente do comum, refrescante e muito agradável.','Mariana S.'],['Gostinho da natureza','Achei a proposta incrível e o pack é perfeito para ter em casa.','Carlos R.'],['Minha nova descoberta','Bonito, saboroso e com uma identidade que chama atenção.','Juliana M.']];document.querySelector('#review-cards').innerHTML=reviews.map((r,i)=>`<article aria-label="Depoimento ${i+1} de ${reviews.length}"><h3>${r[0]}</h3><p>“${r[1]}”</p><footer><b>${r[2]}</b><span class="stars" aria-label="5 estrelas">★★★★★</span></footer></article>`).join('');
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const qty=document.querySelector('#quantity'),cep=document.querySelector('#cep'),shippingResult=document.querySelector('#shipping-result');let freight=null;function update(){qty.value=Math.min(12,Math.max(1,Math.floor(Number(qty.value)||1)));document.querySelector('#price').textContent=money(qty.value*48);document.querySelector('#total').textContent=freight===null?'':`Total simulado: ${money(qty.value*48+freight)}`;document.querySelector('#minus').disabled=qty.value<=1;document.querySelector('#plus').disabled=qty.value>=12}qty.onchange=update;document.querySelector('#minus').onclick=()=>{qty.value--;update()};document.querySelector('#plus').onclick=()=>{qty.value++;update()};cep.oninput=()=>{const digits=cep.value.replace(/\D/g,'').slice(0,8);cep.value=digits.replace(/(\d{5})(\d)/,'$1-$2');freight=null;shippingResult.textContent='Informe seu CEP para simular a entrega.';update()};document.querySelector('#shipping').onsubmit=e=>{e.preventDefault();const digits=cep.value.replace(/\D/g,'');if(digits.length!==8||/^0{8}$/.test(digits)){shippingResult.textContent='Digite um CEP com 8 dígitos.';freight=null}else{freight=Number(digits[0])<=3?12.9:19.9;shippingResult.textContent=`Frete simulado: ${money(freight)} · 3 a 7 dias úteis. Valores fictícios para apresentação.`}update()};document.querySelector('#checkout').onclick=()=>{show(`<p class="eyebrow">Pedido demonstrativo</p><h2>Boa escolha.<br>Um sabor diferente espera por você.</h2><p><strong>${qty.value} pack(s) VITTAIA</strong><br>${qty.value*6} latas de 269 ml</p><p>Subtotal: ${money(qty.value*48)}<br>Frete: ${freight===null?'não calculado':money(freight)+' (simulado)'}</p>${freight===null?'':`<p><strong>Total simulado: ${money(qty.value*48+freight)}</strong></p>`}<small>Esta é uma apresentação acadêmica. Nenhum pedido será enviado, nenhum dado é armazenado e não há cobrança.</small><button class="button green" id="finish-order">Concluir demonstração</button>`);document.querySelector('#finish-order').onclick=()=>show('<h2>Obrigado por conhecer a VITTAIA!</h2><p>Diferente até no sabor.</p><small>Demonstração concluída. Nenhuma compra foi realizada.</small>')};update();
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));
